<section class="card campaigns-module">
    <div class="card-title"><div><h2>Registro de campañas internacionales</h2><small class="filter-help">Seguimiento de paquetes y mensajes de cada campaña.</small></div><span class="result-count">{{ $this->campaignHistory->count() }} campañas</span></div>
    <div class="campaign-list">
        @forelse($this->campaignHistory as $campaign)
            @php($total = max(1, $campaign->total)) @php($progress = min(100, round(($campaign->sent / $total) * 100)))
            <article class="campaign-row"><div class="campaign-row-head"><div><strong>{{ $campaign->name }}</strong><small>{{ $campaign->total }} paquetes · {{ $campaign->messages_count }} mensajes · {{ ucfirst($campaign->status) }}</small></div><span class="campaign-percent">{{ $progress }}%</span></div><div class="campaign-progress" role="progressbar" aria-valuenow="{{ $progress }}" aria-valuemin="0" aria-valuemax="100"><i style="width:{{ $progress }}%"></i></div><div class="campaign-row-actions"><button type="button" class="secondary-btn" wire:click="editCampaign({{ $campaign->id }})">Editar</button><button type="button" class="secondary-btn" onclick="document.getElementById('campaignInfo{{ $campaign->id }}').showModal()">Información</button></div></article>
            <dialog id="campaignInfo{{ $campaign->id }}" class="campaign-history-modal campaign-info-modal"><div class="modal-head"><div><h2>{{ $campaign->name }}</h2><p>Paquetes, teléfonos y respuestas registradas.</p></div><button type="button" class="modal-close" onclick="this.closest('dialog').close()">×</button></div><div class="campaign-info-grid"><div><strong>{{ $campaign->total }}</strong><small>Paquetes</small></div><div><strong>{{ $campaign->messages_count }}</strong><small>Mensajes</small></div><div><strong>{{ $campaign->sent }}</strong><small>Enviados</small></div><div><strong>{{ $campaign->messages()->where('status','replied')->count() }}</strong><small>Respondieron</small></div><div><strong>{{ $campaign->messages()->whereIn('status',['sent','pending'])->count() }}</strong><small>Sin respuesta</small></div></div><div class="campaign-message-table-wrap"><table class="campaign-message-table"><thead><tr><th>Guía</th><th>Teléfono</th><th>Mensaje</th><th>Estado</th></tr></thead><tbody>@foreach($campaign->messages()->with('package')->latest()->get() as $message)<tr><td>{{ $message->package?->tracking_number ?? '—' }}</td><td>{{ $message->phone ?: '—' }}</td><td>{{ $message->message }}</td><td>{{ ucfirst($message->status) }}</td></tr>@endforeach</tbody></table></div></dialog>
        @empty
            <div class="campaign-empty">Aún no hay campañas creadas.</div>
        @endforelse
    </div>
